return ['domain'=>'wegame-tournoi','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'We Game Tournoi 2.4.3','pot-creation-date'=>'2026-09-22T09:57:18+00:00','po-revision-date'=>'2026-09-22T09:57:18+00:00','messages'=>['We Game Tournoi'=>'We Game Tournoi','https://github.com/cparfait/wordpress-tournois'=>'https://github.com/cparfait/wordpress-tournois','Run an esports tournament from WordPress: 2 to 64 teams, single or double elimination, or a group stage, with a live public page.'=>'Gestion et affichage de tournois e-sport (2 à 64 équipes) : élimination directe, double élimination ou phase de poules. Conçu pour We Game 2026, Tournoi Call of Duty.','cparfait'=>'cparfait','https://github.com/cparfait'=>'https://github.com/cparfait','Tournaments'=>'Tournois','Dashboard'=>'Tableau de bord','New tournament'=>'Nouveau tournoi','All tournaments'=>'Tous les tournois','Teams'=>'Équipes','Matches & scores'=>'Matchs & scores','Schedule'=>'Planning','Tournament settings'=>'Réglages du tournoi','Public preview'=>'Aperçu public','Plugin settings'=>'Réglages de l’extension','Plugin'=>'Extension','Copied'=>'Copié','Copy'=>'Copier','Access denied.'=>'Accès refusé.','Tournament'=>'Tournoi','no tournament'=>'aucun tournoi','Edit page'=>'Modifier la page','View'=>'Voir','Delete'=>'Supprimer','Create a tournament'=>'Créer un tournoi','No tournament exists yet. The wizard below guides you through four steps.'=>'Aucun tournoi n’existe pour le moment. L’assistant ci-dessous vous guide en quatre étapes.','Name'=>'Nom','We Game 2027 — Call of Duty'=>'We Game 2027 — Call of Duty','Game'=>'Jeu','Date'=>'Date','Create'=>'Créer','Tournament created as a draft. Next step: add the teams, then publish the page.'=>'Tournoi créé en brouillon. Prochaine étape : ajouter les équipes, puis publier la page.','Tournament created without a dedicated page. Place the shortcodes on your own pages, then add the teams.'=>'Tournoi créé sans page dédiée. Placez les codes courts sur vos pages, puis ajoutez les équipes.','Tournament created and page published. Next step: add the teams.'=>'Tournoi créé et page publiée. Prochaine étape : ajouter les équipes.','Tournament created.'=>'Tournoi créé.','Single elimination'=>'Élimination directe','The simplest and fastest format: one loss and the team is out. Ideal for a single evening.'=>'Le plus simple et le plus rapide : une défaite et l’équipe est éliminée. Idéal pour une soirée.','16 teams: 15 matches'=>'16 équipes : 15 matchs','Double elimination'=>'Double élimination','A team is only out after two losses, thanks to a losers bracket. Longer, but fairer.'=>'Une équipe n’est éliminée qu’après deux défaites, grâce à un tableau de repêchage. Plus long, plus juste.','16 teams: 30 matches'=>'16 équipes : 30 matchs','Group stage then playoffs'=>'Poules puis phase finale','Each team plays several matches in its group, then the best ones face off in a bracket. The longest format.'=>'Chaque équipe joue plusieurs matchs dans sa poule, puis les meilleures s’affrontent en tableau. Le plus long.','16 teams in 4 groups: 24 + 7 matches'=>'16 équipes en 4 poules : 24 + 7 matchs','The tournament'=>'Le tournoi','The format'=>'Le format','Matches and times'=>'Matchs et horaires','Sign-ups and creation'=>'Inscriptions et création','1. The tournament'=>'1. Le tournoi','This information appears at the top of the public page. Only the name is required; everything can be changed later in Tournament settings.'=>'Ces informations apparaissent en tête de la page publique. Seul le nom est obligatoire ; tout se modifie ensuite dans Réglages du tournoi.','Tournament name'=>'Nom du tournoi','It also becomes the title and the address of the tournament page.'=>'Il devient aussi le titre et l’adresse de la page du tournoi.','Call of Duty'=>'Call of Duty','Venue'=>'Lieu','Community hall'=>'Salle des fêtes','First match time'=>'Heure du premier match','Subtitle (optional)'=>'Sous-titre (facultatif)','Amateur tournament open to all'=>'Tournoi amateur ouvert à tous','Accent color'=>'Couleur d’accent','2. The format'=>'2. Le format','Choose how the teams face each other. The match bracket is generated automatically from this choice.'=>'Choisissez comment les équipes s’affrontent. Le tableau des matchs est généré automatiquement d’après ce choix.','Number of teams'=>'Nombre d’équipes','From 2 to 64. If it is not a power of two (8, 16, 32…), the top seeds get a bye in the first round.'=>'De 2 à 64. Si ce n’est pas une puissance de deux (8, 16, 32…), les mieux placées sont exemptées du premier tour.','Players per team'=>'Joueurs par équipe','Number of groups'=>'Nombre de poules','Teams are spread across the groups in snake order according to their seed. You can also build the groups by hand.'=>'Les équipes sont réparties en serpentin selon leur position. Vous pourrez aussi composer les poules à la main.','Qualifiers per group'=>'Qualifiés par poule','Qualifiers are cross-matched between groups for the playoffs.'=>'Les qualifiés sont croisés entre poules pour la phase finale.','Play a third place match between the semi-final losers'=>'Jouer un match pour la 3e place entre les perdants des demi-finales','Bracket reset if the team coming from the losers bracket wins the first grand final (strict rule)'=>'Seconde grande finale si l’équipe venue du repêchage gagne la première (règle stricte)','In double elimination, the loser of the losers bracket final is automatically 3rd.'=>'En double élimination, le perdant de la finale du repêchage est automatiquement 3e.','3. Matches and times'=>'3. Matchs et horaires','The schedule is calculated from these values: each match is given a time and stations. You can then adjust each time by hand.'=>'Le planning est calculé d’après ces valeurs : chaque match reçoit une heure et des postes. Vous pourrez ajuster chaque horaire à la main ensuite.','Number of games per round'=>'Nombre de manches par tour','BO1: one game. BO3: the first team to win two games. BO5: the first to three. A BO3 takes about twice as long as a BO1.'=>'BO1 : une manche. BO3 : la première équipe à deux manches gagnées. BO5 : à trois. Un BO3 dure environ deux fois plus longtemps qu’un BO1.','Group matches'=>'Matchs de poule','Early rounds (round of 64, round of 32)'=>'Premiers tours (32es, 16es)','R16'=>'Huitièmes','Quarters'=>'Quarts','Semi-finals'=>'Demi-finales','Final'=>'Finale','Losers bracket'=>'Repêchage','Stations and durations'=>'Postes et durées','Available gaming stations'=>'Postes de jeu disponibles','Total number of PCs or consoles.'=>'Nombre total de PC ou consoles.','Matches played at the same time'=>'Matchs joués en même temps','With 8 stations and teams of 4, two matches can run simultaneously.'=>'Avec 8 postes et des équipes de 4, deux matchs peuvent se jouer simultanément.','Length of one game (minutes)'=>'Durée d’une manche (minutes)','Setup and team changeover included.'=>'Installation et rotation des équipes comprises.','Check-in before the first match (minutes)'=>'Accueil avant le premier match (minutes)','Break between rounds (minutes)'=>'Pause entre les tours (minutes)','Expected end time'=>'Fin prévisionnelle','Approximate, shown on the public page.'=>'Indicatif, affiché sur la page publique.','4. Sign-ups and creation'=>'4. Inscriptions et création','Two ways to build the teams: enter them yourself in the Teams screen, or open a public form for the players to fill in (requests arrive pending approval).'=>'Deux façons de constituer les équipes : les saisir vous-même dans l’écran Équipes, ou ouvrir un formulaire public que les joueurs remplissent (les demandes arrivent en attente de validation).','Open the public sign-up form on the tournament page'=>'Ouvrir le formulaire d’inscription public sur la page du tournoi','Maximum number of sign-ups'=>'Nombre maximum d’inscriptions','0 = unlimited. A rejected team frees up its slot.'=>'0 = illimité. Une équipe refusée libère sa place.','E-mail notified on each sign-up'=>'E-mail averti à chaque inscription','Message shown after sign-up'=>'Message affiché après l’inscription','Publishing'=>'Publication','Creation generates a dedicated tournament page (listed under "Tournaments › All tournaments", not under "Pages"), with its Bracket, Schedule, Results and Teams tabs and, if you open it, Sign-up. As long as the page is not published, only administrators can see it. Its address is then shown on the dashboard.'=>'La création génère une page dédiée au tournoi (listée dans « Tournois › Tous les tournois », pas dans « Pages »), avec ses onglets Tableau, Planning, Résultats, Équipes et, si vous l’ouvrez, Inscription. Tant que la page n’est pas publiée, seuls les administrateurs la voient. Son adresse s’affiche ensuite sur le tableau de bord.','Publish the page right away'=>'Publier la page tout de suite','The page goes live immediately: players can view it and sign up if the form is open.'=>'La page est en ligne dès maintenant : les joueurs peuvent la consulter et s’inscrire si le formulaire est ouvert.','Keep as a draft'=>'Garder en brouillon','You prepare the teams and the content at your own pace, then publish the page from "All tournaments" or "Edit page".'=>'Vous préparez les équipes et le contenu tranquillement, puis vous publiez la page depuis « Tous les tournois » ou « Modifier la page ».','No dedicated page'=>'Pas de page dédiée','No page is visible for this tournament. You place the bracket, the form or the schedule on your own pages yourself, using the shortcodes.'=>'Aucune page n’est visible pour ce tournoi. Vous placez vous-même le tableau, le formulaire ou le planning sur vos propres pages avec les codes courts.','Also create a dedicated sign-up page'=>'Créer aussi une page d’inscription dédiée','A WordPress page containing only the simplified form (Team, Nickname, E-mail, Phone): ideal for a QR code or a poster. Its address and its QR code will appear on the dashboard.'=>'Une page WordPress ne contenant que le formulaire simplifié (Team, Pseudo, Mail, Téléphone) : idéale pour un QR code ou une affiche. Son adresse et son QR code apparaîtront sur le tableau de bord.','What happens after creation?'=>'Et après la création ?','Links: as soon as the tournament is created, the dashboard shows the address of the tournament page and of the sign-up form, ready to copy or to turn into a QR code.'=>'Liens : dès la création, le tableau de bord affiche l’adresse de la page du tournoi et celle du formulaire d’inscription, prêtes à copier ou à transformer en QR code.','Tournament page: it is created automatically. It does not appear in the WordPress "Pages" menu but under "Tournaments › All tournaments" (the "View" button in the tournament bar). To publish or unpublish it later: "Edit page", then the Publish button. The "No dedicated page" option can be changed in Tournament settings.'=>'Page du tournoi : elle est créée automatiquement. Elle n’apparaît pas dans le menu « Pages » de WordPress mais dans « Tournois › Tous les tournois » (bouton « Voir » de la barre du tournoi). Pour la publier ou la dépublier plus tard : « Modifier la page », puis le bouton Publier. L’option « Pas de page dédiée » se change dans Réglages du tournoi.','Sign-up page: if you open sign-ups, the form is already in the Sign-up tab of the tournament page. You can also create a separate WordPress page, easier to share, by pasting the shortcode below into it, then publish it.'=>'Page d’inscription : si vous ouvrez les inscriptions, le formulaire est déjà dans l’onglet Inscription de la page du tournoi. Vous pouvez aussi créer une page WordPress séparée, plus simple à partager, en y collant le code court ci-dessous, puis la publier.','Sharing: a QR code or a link to one of these pages is all players need to sign up and then follow the tournament live.'=>'Partage : un QR code ou un lien vers l’une de ces pages suffit aux joueurs pour s’inscrire puis suivre le tournoi en direct.','Teams: enter them in the Teams screen or approve the sign-ups received, then assign the seeds. The dashboard reminds you of these steps.'=>'Équipes : saisissez-les dans l’écran Équipes ou validez les inscriptions reçues, puis attribuez les positions. Le tableau de bord vous rappelle ces étapes.','short form (Team, Nickname, E-mail, Phone)'=>'formulaire réduit (Team, Pseudo, Mail, Téléphone)','full form with the player list'=>'formulaire complet avec la liste des joueurs','Summary'=>'Récapitulatif','Format'=>'Format','Matches to play'=>'Matchs à jouer','When'=>'Quand','Estimated end'=>'Fin estimée','Sign-ups'=>'Inscriptions','Tournament page'=>'Page du tournoi','Everything can still be changed after creation. The match bracket is created immediately; it fills in as the teams are given a seed.'=>'Tout reste modifiable après la création. Le tableau des matchs est créé immédiatement ; il se remplit à mesure que les équipes reçoivent une position.','← Previous'=>'← Précédent','Next →'=>'Suivant →','Create the tournament'=>'Créer le tournoi','%d teams'=>'%d équipes','%1$d groups, %2$d qualifiers per group'=>'%1$d poules, %2$d qualifiés par poule','about %d'=>'environ %d','Public form open'=>'Formulaire public ouvert','Entered by the organizers'=>'Saisie par l’organisation','Published immediately'=>'Publiée immédiatement','Draft, to publish later'=>'Brouillon, à publier plus tard','No dedicated page (shortcodes)'=>'Aucune page dédiée (codes courts)','to'=>'à','The tournament name is required.'=>'Le nom du tournoi est obligatoire.','Danger zone: reset or delete the tournament'=>'Zone sensible : réinitialiser ou supprimer le tournoi','These actions cannot be undone and only affect the selected tournament.'=>'Ces actions sont irréversibles et ne concernent que le tournoi sélectionné.','To empty the tournament (teams + results), type REINITIALISER:'=>'Pour vider le tournoi (équipes + résultats), saisissez REINITIALISER :','Permanently delete all teams and all results of this tournament?'=>'Supprimer définitivement toutes les équipes et tous les résultats de ce tournoi ?','Reset'=>'Réinitialiser','To delete the tournament and its page, type SUPPRIMER:'=>'Pour supprimer le tournoi et sa page, saisissez SUPPRIMER :','Permanently delete this tournament, its page and all its data?'=>'Supprimer définitivement ce tournoi, sa page et toutes ses données ?','Delete the tournament'=>'Supprimer le tournoi','Public links'=>'Liens publics','The tournament page is a draft: its address will only work for visitors once it is published.'=>'La page du tournoi est en brouillon : son adresse ne fonctionnera pour les visiteurs qu’après publication.','bracket, schedule, results, teams'=>'tableau, planning, résultats, équipes','Sign-up page'=>'Page d’inscription','to share with players'=>'à partager aux joueurs','not published: publish it to make it accessible'=>'non publiée : publiez-la pour qu’elle soit accessible','Sign-up form'=>'Formulaire d’inscription','Sign-up tab of the tournament page'=>'onglet Inscription de la page du tournoi','Create a dedicated sign-up page'=>'Créer une page d’inscription dédiée','A WordPress page containing only the simplified form: shorter to share and to print as a QR code.'=>'Une page WordPress ne contenant que le formulaire simplifié : plus courte à partager et à imprimer en QR code.','Sign-ups are closed: the form will show "sign-ups closed" until you open them in Tournament settings.'=>'Les inscriptions sont fermées : le formulaire affichera « inscriptions fermées » tant que vous ne les ouvrez pas dans Réglages du tournoi.','This tournament has no dedicated page. Paste these shortcodes into your own pages, then publish them:'=>'Ce tournoi n’a pas de page dédiée. Collez ces codes courts dans vos propres pages, puis publiez-les :','full tabbed page'=>'page complète à onglets','simplified sign-up form'=>'formulaire d’inscription simplifié','bracket only (control room screen)'=>'tableau seul (écran de régie)','Site pages using the shortcodes'=>'Pages du site utilisant les codes courts','not published'=>'non publiée','edit'=>'modifier','Open'=>'Ouvrir','Edit'=>'Modifier','QR code to %s'=>'QR code vers %s','Download the QR code'=>'Télécharger le QR code','PNG'=>'PNG','SVG'=>'SVG','Publish the tournament page'=>'Publier la page du tournoi','The page is a draft: only administrators can see it. Publish it once the content is ready so players can view it and sign up.'=>'La page est en brouillon : seuls les administrateurs la voient. Publiez-la quand le contenu est prêt pour que les joueurs puissent la consulter et s’inscrire.','Edit and publish'=>'Modifier et publier','Build the teams (%1$d / %2$d approved)'=>'Constituer les équipes (%1$d / %2$d validées)','The public form is open: approve the requests received, or add teams yourself.'=>'Le formulaire public est ouvert : validez les demandes reçues, ou ajoutez des équipes vous-même.','Add each team from the Teams screen, or open public sign-ups in Tournament settings.'=>'Ajoutez chaque équipe depuis l’écran Équipes, ou ouvrez les inscriptions publiques dans Réglages du tournoi.','Open Teams'=>'Ouvrir Équipes','Assign the seeds'=>'Attribuer les positions','Each approved team gets a number from 1 to N that places it in the bracket. The "Random draw for seeds" button does it for you.'=>'Chaque équipe validée reçoit un numéro de 1 à N qui la place dans le tableau. Le bouton « Tirage au sort des positions » le fait pour vous.','Place the teams'=>'Placer les équipes','Check the public page'=>'Vérifier la page publique','The tournament page shows the bracket, schedule, results and sign-ups. Its links are in the "Public links" box above.'=>'La page du tournoi affiche tableau, planning, résultats et inscriptions. Ses liens sont dans le bloc « Liens publics » ci-dessus.','View the page'=>'Voir la page','Put the shortcodes on your pages'=>'Placer les codes courts sur vos pages','This tournament has no dedicated page: copy the shortcodes from the "Public links" box into the pages of your choice, then publish them.'=>'Ce tournoi n’a pas de page dédiée : copiez les codes courts du bloc « Liens publics » dans les pages de votre choix, puis publiez-les.','Create a page'=>'Créer une page','On the day: enter the scores'=>'Le jour J : saisir les scores','In Matches & scores, enter the result of each match: the winner automatically moves on to the next round and the public page updates by itself.'=>'Dans Matchs & scores, entrez le résultat de chaque match : le vainqueur passe automatiquement au tour suivant et la page publique se met à jour toute seule.','Open Matches & scores'=>'Ouvrir Matchs & scores','Next steps'=>'Prochaines étapes','Tournament duplicated.'=>'Tournoi dupliqué.','Tournament not found.'=>'Tournoi introuvable.','Tournament settings saved.'=>'Réglages du tournoi enregistrés.','Team saved.'=>'Équipe enregistrée.','Team deleted.'=>'Équipe supprimée.','Result saved.'=>'Résultat enregistré.','No tournament selected.'=>'Aucun tournoi sélectionné.','%d team(s) placed randomly in the bracket.'=>'%d équipe(s) placée(s) aléatoirement dans le tableau.','All results have been reset to zero.'=>'Tous les résultats ont été remis à zéro.','Bracket regenerated.'=>'Tableau régénéré.','Schedule recalculated from the tournament settings.'=>'Planning recalculé d’après les réglages du tournoi.','All pending sign-ups have been approved.'=>'Toutes les inscriptions en attente ont été validées.','Reset cancelled: the confirmation word does not match.'=>'Réinitialisation annulée : le mot de confirmation ne correspond pas.','Tournament reset: teams and results deleted, empty bracket recreated.'=>'Tournoi réinitialisé : équipes et résultats supprimés, tableau vierge recréé.','Deletion cancelled: the confirmation word does not match.'=>'Suppression annulée : le mot de confirmation ne correspond pas.','Tournament deleted.'=>'Tournoi supprimé.','Unknown action.'=>'Action inconnue.','Settings saved.'=>'Réglages enregistrés.','No file received.'=>'Aucun fichier reçu.','The file upload failed.'=>'Le téléversement du fichier a échoué.','File empty or too large (5 MB maximum).'=>'Fichier vide ou trop volumineux (5 Mo maximum).','The file could not be read.'=>'Impossible de lire le fichier.','Backup restored.'=>'Sauvegarde restaurée.','English'=>'Anglais','We Game Tournoi is ready.'=>'We Game Tournoi est prêt.','The plugin follows your site language (%s). You can pick another one in its settings.'=>'L’extension suit la langue de votre site (%s). Vous pouvez en choisir une autre dans ses réglages.','Choose the language'=>'Choisir la langue','Dismiss'=>'Masquer','Sign-up page created and published.'=>'Page d’inscription créée et publiée.','[%s] We Game Tournoi test email'=>'[%s] E-mail de test We Game Tournoi','If you receive this message, the site can send sign-up notifications.'=>'Si vous recevez ce message, le site peut envoyer les notifications d’inscription.','Test email handed to the server for %s. Check the inbox (and the spam folder); if it does not arrive, your hosting does not relay emails: install an SMTP plugin.'=>'E-mail de test remis au serveur pour %s. Vérifiez la boîte de réception (et les indésirables) ; s’il n’arrive pas, l’hébergement ne relaie pas les e-mails : installez une extension SMTP.','The server could not send the email: %s. Set up sending (SMTP plugin) before opening sign-ups.'=>'Le serveur n’a pas pu envoyer l’e-mail : %s. Configurez l’envoi (extension SMTP) avant d’ouvrir les inscriptions.','no mail function available'=>'aucune fonction mail disponible','No valid manifest could be retrieved. Check the URL (the package must be served over HTTPS).'=>'Aucun manifeste valide n’a pu être récupéré. Vérifiez l’URL (le paquet doit être servi en HTTPS).','Version %s available. Go to the Plugins page to install it.'=>'Version %s disponible. Rendez-vous sur la page Extensions pour l’installer.','The plugin is up to date.'=>'L’extension est à jour.','Preview'=>'Aperçu','Signed-up teams'=>'Équipes inscrites','Approved teams'=>'Équipes validées','Seeds assigned'=>'Positions attribuées','Matches played'=>'Matchs joués','Winner:'=>'Vainqueur :','Third place:'=>'3e place :','The bracket is not complete: assign a seed (1 to %d) to each approved team from the Teams screen.'=>'Le tableau n’est pas complet : attribuez une position (1 à %d) à chaque équipe validée depuis l’écran Équipes.','Incomplete groups: %s. A group must have at least 2 approved teams for its matches to exist; assign a group to each team from the Teams screen.'=>'Poules incomplètes : %s. Une poule doit compter au moins 2 équipes validées pour que ses matchs existent ; attribuez une poule à chaque équipe depuis l’écran Équipes.','Unbalanced groups: %1$s (reference size: %2$d). Each group plays its own matches, but a larger group plays more of them; the number of qualified teams is limited by the smallest group.'=>'Poules déséquilibrées : %1$s (effectif de référence : %2$d). Chaque poule joue ses propres matchs, mais une poule plus grande joue davantage de rencontres ; le nombre de qualifiés est limité par la plus petite poule.','Bracket preview'=>'Aperçu du tableau','Tools'=>'Outils','Regenerate the bracket'=>'Régénérer le tableau','Random draw for seeds'=>'Tirage au sort des positions','Reset all results to zero? The teams are kept.'=>'Remettre tous les résultats à zéro ? Les équipes sont conservées.','Reset all results'=>'Remise à zéro des résultats','Backup'=>'Sauvegarde','The backup only covers the selected tournament.'=>'La sauvegarde ne concerne que le tournoi sélectionné.','Download a backup (JSON)'=>'Télécharger une sauvegarde (JSON)','Restore a backup into this tournament'=>'Restaurer une sauvegarde dans ce tournoi','Also restore the tournament settings'=>'Restaurer aussi les réglages du tournoi','Replace this tournament\'s data with the contents of the file?'=>'Remplacer les données de ce tournoi par le contenu du fichier ?','Restore'=>'Restaurer','Duplicate this tournament'=>'Dupliquer ce tournoi','Carries over the settings and the format, without the results. Ideal for preparing the next edition.'=>'Reprend les réglages et le format, sans les résultats. Idéal pour préparer l’édition suivante.','Name of the new tournament'=>'Nom du nouveau tournoi','Also carry over the teams (pending approval, without a seed)'=>'Reprendre aussi les équipes (en attente de validation, sans position)','Duplicate'=>'Dupliquer','Shortcodes'=>'Codes courts','The tournament page already shows everything automatically: these shortcodes are only useful if you want the same content elsewhere on the site.'=>'La page du tournoi affiche déjà tout automatiquement : ces codes courts ne servent que si vous voulez le même contenu ailleurs sur le site.','How to use them:'=>'Comment s’en servir :','create a WordPress page (Pages › Add New), paste the shortcode you want into it, then click Publish. The tournament content will appear on that page, and will update by itself during the event.'=>'créez une page WordPress (Pages › Ajouter), collez-y le code court voulu, puis cliquez sur Publier. Le contenu du tournoi s’affichera sur cette page, et se mettra à jour tout seul pendant la soirée.','Shortcode'=>'Code court','Display'=>'Affichage','List of all tournaments on the site'=>'Liste de tous les tournois du site','Full tabbed page'=>'Page complète à onglets','Single-elimination bracket'=>'Tableau à élimination directe','Time schedule'=>'Planning horaire','Results sheet'=>'Feuille de résultats','Overall ranking'=>'Classement général','Group standings'=>'Classements des poules','Participating teams'=>'Équipes engagées','Rules'=>'Règlement','Staff needed'=>'Personnel nécessaire','Pre-opening checklist'=>'Checklist avant ouverture','Sign-up form (simple="yes": Team, Nickname, Email, Phone)'=>'Formulaire d’inscription (simple="yes" : Team, Pseudo, Mail, Téléphone)','Without the "tournoi" attribute, the shortcode shows the site\'s default tournament. A page containing a shortcode stays invisible to visitors until it is published.'=>'Sans l’attribut « tournoi », le code court affiche le tournoi par défaut du site. Une page contenant un code court reste invisible aux visiteurs tant qu’elle n’est pas publiée.','Create a page now'=>'Créer une page maintenant','Pending'=>'En attente','Approved'=>'Validée','Rejected'=>'Refusée','Edit team'=>'Modifier l’équipe','Add a team'=>'Ajouter une équipe','Team name'=>'Nom de l’équipe','Tag'=>'Tag','Seed in the bracket (1 to %d)'=>'Position dans le tableau (1 à %d)','— unseeded —'=>'— non placée —','Group'=>'Poule','— unassigned —'=>'— non attribuée —','Captain'=>'Capitaine','Email'=>'E-mail','Phone'=>'Téléphone','Players (one per line)'=>'Joueurs (un par ligne)','Internal notes'=>'Notes internes','Status'=>'Statut','Only approved teams appear in the bracket.'=>'Seules les équipes validées apparaissent dans le tableau.','Save'=>'Enregistrer','Cancel'=>'Annuler','Approve pending sign-ups'=>'Valider les inscriptions en attente','Random draw for the free seeds'=>'Tirage au sort des positions libres','Seed'=>'Pos.','Team'=>'Équipe','Contact'=>'Contact','Actions'=>'Actions','No team in this tournament.'=>'Aucune équipe pour ce tournoi.','Delete this team?'=>'Supprimer cette équipe ?','Confirm a match to send the winner to the next round automatically. Editing a result already confirmed resets the following matches involved.'=>'Validez un match pour qualifier automatiquement le vainqueur au tour suivant. Modifier un résultat déjà validé réinitialise les matchs suivants concernés.','Game %d'=>'Manche %d','Map / mode'=>'Carte / mode','Leave unplayed games empty. In BO%1$d, the winner must win %2$d of them.'=>'Laissez vides les manches non jouées. En BO%1$d, le vainqueur doit en remporter %2$d.','Score'=>'Score','Stations'=>'Postes','Start'=>'Début','Referee'=>'Arbitre','Reset every result to zero?'=>'Remettre tous les résultats à zéro ?','Schedule & score sheet'=>'Planning & feuille de scores','Print'=>'Imprimer','Recalculate every time and station from the settings? Manual adjustments will be lost.'=>'Recalculer tous les horaires et postes d’après les réglages ? Les ajustements manuels seront perdus.','Recalculate the schedule'=>'Recalculer le planning','Score sheet'=>'Feuille de scores','Match'=>'Match','Staff'=>'Personnel','Full page (tabs)'=>'Page complète (onglets)','Bracket'=>'Tableau','Results'=>'Résultats','Ranking'=>'Classement','Sign-up'=>'Inscription','Tournament list'=>'Liste des tournois','Desktop'=>'Bureau','Tablet'=>'Tablette','Mobile'=>'Mobile','Exactly what visitors will see. The theme wrapper (menu, footer) is not reproduced here.'=>'Rendu exact de ce que verront les visiteurs. L’habillage du thème (menu, pied de page) n’est pas reproduit ici.','Displayed view'=>'Vue','Width'=>'Largeur','Preview of the public display'=>'Aperçu du rendu public','Rename'=>'Renommer','The name and the page address are changed from the tournament page.'=>'Le nom et l’adresse de la page se modifient depuis la page du tournoi.','Subtitle'=>'Sous-titre','Times'=>'Horaires','Changing the start time shifts the whole schedule automatically.'=>'Modifier l’heure de début décale automatiquement tout le planning.','Gaming stations'=>'Postes de jeu','Double elimination (with losers bracket)'=>'Double élimination (avec repêchage)','Tournament format'=>'Déroulement','In double elimination, a team is only eliminated after two losses. In groups, each team meets every other team of its group before the final phase.'=>'En double élimination, une équipe n’est éliminée qu’après deux défaites. En poules, chaque équipe rencontre toutes celles de sa poule avant la phase finale.','From 2 to 64. If the number is not a power of two, the top seeds get a bye in the first round.'=>'De 2 à 64. Si le nombre n’est pas une puissance de deux, les mieux classées sont exemptées du premier tour.','Groups'=>'Poules','Make-up'=>'Composition','Automatic (snake order by seed)'=>'Automatique (serpentin selon les positions)','Manual (group chosen for each team)'=>'Manuelle (poule choisie pour chaque équipe)','With manual make-up, the group is chosen on each team\'s record. Qualified teams are crossed between groups either way.'=>'En composition manuelle, la poule se choisit sur la fiche de chaque équipe. Les qualifiés sont croisés entre poules dans les deux cas.','R64'=>'32es','R32'=>'Seizièmes','Semis'=>'Demies','Number of games'=>'Nombre de manches','Only the rounds actually present in the chosen format are used.'=>'Seuls les tours réellement présents dans le format choisi sont utilisés.','Third place match'=>'Match pour la 3e place','Pit the two semi-final losers against each other'=>'Opposer les deux perdants des demi-finales','Not applicable in double elimination: the loser of the losers bracket final is third.'=>'Sans objet en double élimination : le perdant de la finale du repêchage est 3e.','Bracket reset'=>'Seconde grande finale','Replay the final if the team coming from the losers bracket wins it (« bracket reset »)'=>'Rejouer la finale si l’équipe issue du repêchage l’emporte (« bracket reset »)','Strict double elimination rule: the team coming from the losers bracket already has one loss, so it must inflict two. The match is only played if needed.'=>'Règle stricte de la double élimination : l’équipe venue du repêchage a déjà une défaite, elle doit donc en infliger deux. Le match n’est joué que si nécessaire.','Time calculation'=>'Calcul des horaires','Match length (min)'=>'Durée d’un match (min)','Simultaneous matches'=>'Matchs simultanés','Welcome time before the 1st match (min)'=>'Accueil avant le 1er match (min)','Break between rounds (min)'=>'Pause entre les tours (min)','A BO3 counts as two slots, a BO5 as three. Times already set are not overwritten: use « Recalculate the schedule » below to regenerate them.'=>'Un BO3 compte pour deux créneaux, un BO5 pour trois. Les horaires déjà en place ne sont pas écrasés : utilisez « Recalculer le planning » ci-dessous pour les régénérer.','Tabs'=>'Onglets','Organisation (staff)'=>'Organisation (personnel)','Dedicated public page'=>'Page publique dédiée','Unchecked, the tournament page answers « not found » to visitors; the tournament is then shown only by the shortcodes placed on your own pages.'=>'Décochée, la page du tournoi répond « introuvable » aux visiteurs ; le tournoi ne s’affiche que par les codes courts placés sur vos propres pages.','Show the tournament automatically on its page'=>'Afficher automatiquement le tournoi sur sa page','Uncheck if you prefer to build the page yourself with the shortcodes.'=>'Décochez si vous préférez composer la page vous-même avec les codes courts.','Public form'=>'Formulaire public','Open sign-ups for this tournament'=>'Ouvrir les inscriptions pour ce tournoi','Maximum number of teams'=>'Nombre maximum d’équipes','Notification email'=>'E-mail de notification','Notified on every sign-up. Empty: the site administration address. The captain gets an acknowledgement of his own.'=>'Prévenu à chaque inscription. Vide : adresse d’administration du site. Le capitaine reçoit de son côté un accusé de réception.','Confirmation message'=>'Message de confirmation','Language'=>'Langue','Same as the site'=>'Identique au site','Language of the tournament screens and of the public page. Choose "Same as the site" to follow the site language.'=>'Langue des écrans du tournoi et de la page publique. Choisissez « Identique au site » pour suivre la langue du site.','Default tournament'=>'Tournoi par défaut','No published tournament.'=>'Aucun tournoi publié.','— the most recent —'=>'— le plus récent —','Used by the shortcodes without a « tournoi » attribute.'=>'Utilisé par les codes courts sans attribut « tournoi ».','Auto refresh'=>'Rafraîchissement auto','seconds (0 to disable)'=>'secondes (0 pour désactiver)','Page title'=>'Titre de la page','Hide the theme title banner on tournament pages'=>'Masquer le bandeau de titre du thème sur les pages de tournoi','Additional CSS selectors'=>'Sélecteurs CSS supplémentaires','Update manifest URL'=>'URL du manifeste de mise à jour','Leave empty to disable automatic updates.'=>'Laissez vide pour désactiver les mises à jour automatiques.','Version %1$s is available (you are running %2$s).'=>'Version %1$s disponible (vous utilisez la %2$s).','Up to date (version %s).'=>'À jour (version %s).','Data on uninstall'=>'Données à la désinstallation','Delete everything if the plugin is uninstalled'=>'Tout supprimer si l’extension est désinstallée','Unchecked (recommended), tournaments and their data are kept.'=>'Décoché (recommandé), les tournois et leurs données sont conservés.','Check for updates now'=>'Vérifier les mises à jour maintenant','Emails'=>'E-mails','Every public sign-up sends an acknowledgement to the captain and an alert to the tournament notification address (failing that, the site administration address). Delivery depends on your hosting: test it here.'=>'Chaque inscription publique envoie un accusé de réception au capitaine et une alerte à l’adresse de notification du tournoi (à défaut, l’adresse d’administration du site). L’envoi dépend de l’hébergement : testez-le ici.','Send a test email to'=>'Envoyer un e-mail de test à','Send'=>'Envoyer','Quarter-finals'=>'Quarts de finale','Round of 16'=>'Huitièmes de finale','Round of 32'=>'Seizièmes de finale','Round of 64'=>'Trente-deuxièmes de finale','Group stage'=>'Phase de poules','Grand final'=>'Grande finale','Losers bracket — round %d'=>'Repêchage — tour %d','Third place'=>'3e place','Losers round %d'=>'Repêchage %d','Tournament manager'=>'Responsable tournoi','Supervision, rules, decisions and coordination'=>'Supervision, règlement, décisions et coordination','Front desk / management'=>'Accueil / gestion','Sign-ups, results, bracket and times'=>'Inscriptions, résultats, tableau et horaires','Referees'=>'Arbitres','Match follow-up, score approval, disputes'=>'Suivi des matchs, validation des scores, litiges','Technicians'=>'Techniciens','Stations, network, accounts, peripherals, incidents'=>'Postes, réseau, comptes, périphériques, incidents','Host / communication'=>'Animateur / communication','Announcements, atmosphere, hosting, prize ceremony'=>'Annonces, ambiance, présentation, remise des prix','Each team is made up of %d starting player; a substitute is recommended.'=>'Chaque équipe est composée de %d joueur titulaire ; un remplaçant est recommandé.' . "\0" . 'Chaque équipe est composée de %d joueurs titulaires ; un remplaçant est recommandé.','The captain is the team\'s official contact.'=>'Le capitaine est le contact officiel de l’équipe.','Players must follow the instructions of the referees and the organizers.'=>'Les joueurs doivent respecter les consignes des arbitres et de l’organisation.','Any cheat, deliberate exploit or unsportsmanlike behavior may lead to a penalty or a disqualification.'=>'Tout cheat, exploit volontaire ou comportement antisportif peut entraîner une sanction ou une disqualification.','Technical problems must be reported to the referee immediately.'=>'Les problèmes techniques doivent être signalés immédiatement à l’arbitre.','Results are approved by the referee before moving on to the next round.'=>'Les résultats sont validés par l’arbitre avant passage au tour suivant.','The organizers may adjust the schedule in the event of a technical problem or a significant delay.'=>'L’organisation peut adapter le planning en cas de problème technique ou de retard important.','Check the stations and peripherals'=>'Vérifier les postes et périphériques','Test the network and the connection to game services'=>'Tester réseau et connexion aux services de jeu','Check the accounts / profiles used'=>'Vérifier les comptes / profils utilisés','Prepare the tournament bracket and the score sheets'=>'Préparer le tableau du tournoi et les feuilles de scores','Identify the team captains'=>'Identifier les capitaines des équipes','Brief the players and referees'=>'Faire le briefing joueurs et arbitres','Prepare prizes / trophy / rewards'=>'Préparer lots / trophée / récompenses','Plan for water, breaks and a waiting area'=>'Prévoir eau, pauses et espace d’attente','The team name is required.'=>'Le nom de l’équipe est obligatoire.','The seed must be between 1 and %d (0 = unseeded).'=>'La position doit être comprise entre 1 et %d (0 = non placée).','Seed #%d is already taken by another team.'=>'La position n°%d est déjà occupée par une autre équipe.','Match not found.'=>'Match introuvable.','In BO%1$d, the match ends as soon as %2$d games are won: remove the extra games.'=>'En BO%1$d, le match s’arrête dès que %2$d manches sont remportées : supprimez les manches en trop.','Game %d is tied: a game must have a winner.'=>'La manche %d est à égalité : une manche doit avoir un vainqueur.','Both teams must be known before the match can be approved.'=>'Les deux équipes doivent être connues avant de valider le match.','A single-elimination match cannot end in a tie.'=>'Un match à élimination directe ne peut pas se terminer sur une égalité.','In BO%1$d, the winner must win %2$d games.'=>'En BO%1$d, le vainqueur doit remporter %2$d manches.','Winner of %s'=>'Vainqueur %s','Loser of %s'=>'Perdant %s','Team %1$d of group %2$s'=>'Équipe %1$d de la poule %2$s','%1$d%2$s in group %3$s'=>'%1$d%2$s de la poule %3$s','st'=>'er','th'=>'e','Bye'=>'Exempt','Team #%d'=>'Équipe n°%d','To be determined'=>'À déterminer','Target tournament not found.'=>'Tournoi de destination introuvable.','Unreadable file: this is not valid JSON.'=>'Fichier illisible : ce n’est pas du JSON valide.','This file does not come from the We Game Tournoi plugin.'=>'Ce fichier ne provient pas de l’extension We Game Tournoi.','This file was produced by a newer version of the plugin.'=>'Ce fichier a été produit par une version plus récente de l’extension.','Incomplete backup: teams or matches are missing.'=>'Sauvegarde incomplète : équipes ou matchs manquants.','Restore aborted: a team could not be saved. No data was kept.'=>'Restauration interrompue : une équipe n’a pas pu être enregistrée. Aucune donnée n’a été conservée.','Restore aborted: a match could not be saved. No data was kept.'=>'Restauration interrompue : un match n’a pas pu être enregistré. Aucune donnée n’a été conservée.','Restore aborted: a game could not be saved. No data was kept.'=>'Restauration interrompue : une manche n’a pas pu être enregistrée. Aucune donnée n’a été conservée.','Team no. %d is unreadable.'=>'Équipe n° %d illisible.','Team no. %d has no name.'=>'Équipe n° %d sans nom.','Match no. %d is unreadable.'=>'Match n° %d illisible.','Match no. %d has no code.'=>'Match n° %d sans code.','Duplicate match code "%s".'=>'Code de match « %s » en double.','Game no. %d is unreadable.'=>'Manche n° %d illisible.','Session expired, please submit the form again.'=>'Session expirée, merci de renvoyer le formulaire.','Thank you, your sign-up has been recorded.'=>'Merci, votre inscription a bien été enregistrée.','Sign-ups are closed.'=>'Les inscriptions sont fermées.','You must accept the rules.'=>'Vous devez accepter le règlement.','Too many requests sent from this connection. Please try again in an hour.'=>'Trop de demandes envoyées depuis cette connexion. Merci de réessayer dans une heure.','The maximum number of teams has been reached.'=>'Le nombre maximum d’équipes est atteint.','[%1$s] New sign-up: %2$s'=>'[%1$s] Nouvelle inscription : %2$s','New sign-up request received.'=>'Nouvelle demande d’inscription reçue.','Team:'=>'Équipe :','Captain:'=>'Capitaine :','Email:'=>'E-mail :','Phone:'=>'Téléphone :','Players:'=>'Joueurs :','[%1$s] Sign-up received: %2$s'=>'[%1$s] Inscription reçue : %2$s','Hello, the sign-up request for team "%s" has been received.'=>'Bonjour, la demande d’inscription de l’équipe « %s » a bien été reçue.','It will be reviewed by the organizers, who will get back to you if needed.'=>'Elle sera validée par l’organisation, qui vous recontactera si nécessaire.','Follow the tournament:'=>'Suivre le tournoi :','No tournament has been created yet.'=>'Aucun tournoi n’a encore été créé.','Starts at %s'=>'Début %s','%d gaming stations'=>'%d postes de jeu','Tournament winner'=>'Vainqueur du tournoi','Third place: %s'=>'3e place : %s','This tournament has no group stage.'=>'Ce tournoi ne comporte pas de phase de poules.','Group %s'=>'Poule %s','P'=>'J','W'=>'V','L'=>'D','Diff.'=>'Diff.','Stations %s'=>'Postes %s','In progress'=>'En cours','Games:'=>'Manches :','No match scheduled.'=>'Aucun match programmé.','Time'=>'Horaire','Match %d'=>'Match %d','Not scheduled'=>'Non programmé','Times are indicative: they assume matches without significant delay. A match played over several games may push back the rest of the schedule.'=>'Les horaires sont indicatifs : ils supposent des matchs sans retard important. Un match en plusieurs manches peut décaler la suite du planning.','vs'=>'vs','No team approved yet.'=>'Aucune équipe validée pour le moment.','Captain: %s'=>'Capitaine : %s','%d player'=>'%d joueur' . "\0" . '%d joueurs','Round'=>'Tour','Team 1'=>'Équipe 1','Team 2'=>'Équipe 2','To play'=>'À jouer','Finished'=>'Terminé','Match format'=>'Format des matchs','BO1: a single game, the team that wins it qualifies.'=>'BO1 : une seule partie, l’équipe qui la remporte se qualifie.','BO3: up to three games, the first team to win two takes the match.'=>'BO3 : jusqu’à trois parties, la première équipe à en gagner deux remporte le match.','Teams of %d starting players, one substitute recommended.'=>'Équipes de %d joueurs titulaires, un remplaçant recommandé.','A third place match pits the two semi-final losers against each other.'=>'Un match pour la 3e place oppose les deux perdants des demi-finales.','Role'=>'Fonction','Qty.'=>'Nb.','Main duties'=>'Missions principales','Winner: %s'=>'Vainqueur : %s','The ranking will build up as matches are played.'=>'Le classement apparaîtra au fil des matchs.','Rank'=>'Rang','Starting seed'=>'Position de départ','Teams eliminated in the same round share the same rank, marked with a "+". The ranking becomes more precise as matches are approved.'=>'Les équipes éliminées au même tour partagent le même rang, signalé par un « + ». Le classement se précise à mesure que les matchs sont validés.','Team sign-up'=>'Inscription d’une équipe','Sign-ups are currently closed.'=>'Les inscriptions sont actuellement fermées.','Do not fill in'=>'Ne pas remplir','short sign-up form labelTeam'=>'Team','Tag (optional)'=>'Tag (facultatif)','Nickname'=>'Pseudo','Mail'=>'Mail','Captain\'s email'=>'E-mail du capitaine','Players (%d starters + substitute, one per line)'=>'Joueurs (%d titulaires + remplaçant, un par ligne)','I accept the tournament rules.'=>'J’accepte le règlement du tournoi.','Send sign-up'=>'Envoyer l’inscription','Organizers'=>'Organisation','Unknown view.'=>'Vue inconnue.','Add'=>'Ajouter','Add a tournament'=>'Ajouter un tournoi','Edit tournament'=>'Modifier le tournoi','View tournament'=>'Voir le tournoi','Search a tournament'=>'Rechercher un tournoi','No tournament'=>'Aucun tournoi','No tournament in the trash'=>'Aucun tournoi dans la corbeille','Source tournament not found.'=>'Tournoi source introuvable.','Sign-up — %s'=>'Inscription — %s','The SHA-256 hash of the downloaded package does not match the one declared in the manifest: installation refused.'=>'L’empreinte SHA-256 du paquet téléchargé ne correspond pas à celle annoncée par le manifeste : installation refusée.','Updated'=>'Mis à jour','Offline — retrying'=>'Hors ligne — nouvelle tentative en cours']];